int n = polygon.size();
    if (n < 3) {
        return ON_UNBOUNDED_SIDE;
    }

    // Ray casting algorithm to check point in polygon
    CGAL::Bounded_side result = ON_UNBOUNDED_SIDE;
    int i;
    for (i = 0; i < n; i++) {
        if (polygon[i].x() == point.x() && polygon[i].y() == point.y()) {
            result = ON_BOUNDARY;
        }
    }

    if (result != ON_BOUNDARY) {
        // Point is on the boundary
        // We need to check if the point is on the boundary of the polygon
        // This means that the point is on one of the lines
        for (const auto& p : polygon) {
            if (p.x() == point.x() && p.y() == point.y()) {
                result = ON_BOUNDED_SIDE;
            }
        }
    }
}

